// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {IHooks} from "v4-core/src/interfaces/IHooks.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {PoolId} from "v4-core/src/types/PoolId.sol";
import {Currency} from "v4-core/src/types/Currency.sol";
import {BalanceDelta, toBalanceDelta} from "v4-core/src/types/BalanceDelta.sol";
import {SwapParams} from "v4-core/src/types/PoolOperation.sol";
import {Hooks} from "v4-core/src/libraries/Hooks.sol";
import {PegFeeHook} from "src/PegFeeHook.sol";

/// @dev USDC-like token: `transfer` to a blacklisted account reverts, as FiatToken's `notBlacklisted` does.
contract BlacklistableToken {
    uint8 public immutable decimals;
    mapping(address => uint256) public balanceOf;
    mapping(address => bool) public isBlacklisted;

    constructor(uint8 d) {
        decimals = d;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function blacklist(address a) external {
        isBlacklisted[a] = true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(!isBlacklisted[msg.sender] && !isBlacklisted[to], "Blacklistable: account is blacklisted");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

/// @dev The slice of the PoolManager an afterSwap surcharge touches, with v4's semantics: `extsload` serves
/// `getSlot0`, `take` transfers from the manager's own balance at once (and bubbles a failing transfer), and
/// `mint` credits an ERC-6909 claim that needs no balance and no transfer. It drives `afterSwap` as the manager.
contract ManagerStub {
    mapping(bytes32 => bytes32) public slots;
    mapping(address => mapping(uint256 => uint256)) public balanceOf; // ERC-6909 claims
    mapping(address => mapping(uint256 => int256)) public delta;

    function setSqrtPrice(PoolId id, uint160 sqrtPriceX96) external {
        // Pool.State is at _pools[id], slot 6 of the PoolManager; slot0 packs sqrtPriceX96 in its low 160 bits.
        slots[keccak256(abi.encode(id, uint256(6)))] = bytes32(uint256(sqrtPriceX96));
    }

    function extsload(bytes32 slot) external view returns (bytes32) {
        return slots[slot];
    }

    function take(Currency currency, address to, uint256 amount) external {
        delta[msg.sender][uint256(uint160(Currency.unwrap(currency)))] -= int256(amount);
        BlacklistableToken(Currency.unwrap(currency)).transfer(to, amount);
    }

    function mint(address to, uint256 id, uint256 amount) external {
        delta[msg.sender][id] -= int256(amount);
        balanceOf[to][id] += amount;
    }

    function burn(address from, uint256 id, uint256 amount) external {
        delta[msg.sender][id] += int256(amount);
        balanceOf[from][id] -= amount;
    }

    function sync(Currency) external {}

    function settle() external payable returns (uint256) {
        return 0;
    }

    function callAfterSwap(IHooks hook, PoolKey memory key, SwapParams memory params, BalanceDelta d)
        external
        returns (bytes4 sel, int128 hookDelta)
    {
        (sel, hookDelta) = hook.afterSwap(address(this), key, params, d, "");
        // the manager credits the hook its returned delta in the unspecified currency
        bool specifiedIs0 = params.amountSpecified < 0 == params.zeroForOne;
        Currency c = specifiedIs0 ? key.currency1 : key.currency0;
        delta[address(hook)][uint256(uint160(Currency.unwrap(c)))] += hookDelta;
    }
}

/// @notice Finding: `afterSwap` sends the surcharge with `take()`, an immediate ERC-20 transfer to the Treasury.
/// If USDC blacklists the Treasury, every exact-input sale of imdUSD that ends below the band (and every
/// exact-output purchase that ends above it) reverts, for as long as the hook lives: it has no owner and no
/// other path for the surcharge. Expected: the swap goes through and the swapper still pays the surcharge,
/// held as an ERC-6909 claim for the Treasury (or the hook) when the transfer cannot be made.
contract BlacklistedTreasuryTest is Test {
    address constant TREASURY = address(0x7EA5);

    ManagerStub pm;
    BlacklistableToken imdusd;
    BlacklistableToken usdc;
    PegFeeHook hook;
    PoolKey key;

    function setUp() public {
        pm = new ManagerStub();
        imdusd = new BlacklistableToken(18);
        usdc = new BlacklistableToken(6);
        hook = _deployHook();
        (address c0, address c1) = hook.stableIsToken0() ? (hook.stable(), hook.quote()) : (hook.quote(), hook.stable());
        key = PoolKey(Currency.wrap(c0), Currency.wrap(c1), 100, 1, IHooks(address(hook)));
        // The manager holds plenty of both currencies (mainnet: USDC from every v4 pool).
        usdc.mint(address(pm), 1e15);
        imdusd.mint(address(pm), 1e27);
    }

    function _deployHook() private returns (PegFeeHook h) {
        bytes memory init = abi.encodePacked(
            type(PegFeeHook).creationCode, abi.encode(IPoolManager(address(pm)), imdusd, usdc, TREASURY)
        );
        bytes32 initHash = keccak256(init);
        uint160 flags = Hooks.BEFORE_INITIALIZE_FLAG | Hooks.AFTER_SWAP_FLAG | Hooks.AFTER_SWAP_RETURNS_DELTA_FLAG;
        for (uint256 salt;; ++salt) {
            address a = vm.computeCreate2Address(bytes32(salt), initHash, address(this));
            if (uint160(a) & Hooks.ALL_HOOK_MASK == flags) {
                h = new PegFeeHook{salt: bytes32(salt)}(IPoolManager(address(pm)), address(imdusd), address(usdc), TREASURY);
                require(address(h) == a);
                return h;
            }
        }
    }

    /// @dev sqrtPriceX96 at which imdUSD is worth `priceE18` USDC (1e18 = $1).
    function _sqrtAt(uint256 priceE18) private view returns (uint160) {
        uint256 rel = hook.stableIsToken0() ? priceE18 : 1e36 / priceE18;
        return uint160(uint256(hook.pegSqrtPriceX96()) * _sqrt(rel * 1e18) / 1e18);
    }

    function _sqrt(uint256 x) private pure returns (uint256 y) {
        y = x;
        uint256 z = (x + 1) / 2;
        while (z < y) (y, z) = (z, (x / z + z) / 2);
    }

    function test_exactInputSaleBelowTheBandSurvivesABlacklistedTreasury() public {
        usdc.blacklist(TREASURY);

        // An exact-input sale of 10,000 imdUSD that ended at $0.99 and produced 9,900 USDC.
        bool zeroForOne = hook.stableIsToken0();
        uint160 endSqrtPrice = _sqrtAt(0.99e18);
        pm.setSqrtPrice(key.toId(), endSqrtPrice);
        SwapParams memory params = SwapParams(zeroForOne, -int256(10_000e18), 0);
        BalanceDelta d = zeroForOne ? toBalanceDelta(-10_000e18, 9_900e6) : toBalanceDelta(9_900e6, -10_000e18);

        uint256 pips = hook.surchargeFor(endSqrtPrice, zeroForOne);
        assertGt(pips, 0, "the swap ended below the band, away from $1");
        uint256 expected = 9_900e6 * pips / 1_000_000;

        // Today: PoolManager.take -> USDC.transfer(TREASURY) -> "Blacklistable: account is blacklisted" -> the swap reverts.
        (bytes4 sel, int128 hookDelta) = pm.callAfterSwap(IHooks(address(hook)), key, params, d);

        assertEq(sel, IHooks.afterSwap.selector);
        assertEq(uint256(int256(hookDelta)), expected, "the swapper still pays exactly the surcharge");
        uint256 id = uint256(uint160(address(usdc)));
        uint256 held = usdc.balanceOf(TREASURY) + pm.balanceOf(TREASURY, id) + pm.balanceOf(address(hook), id);
        assertEq(held, expected, "the surcharge is held for the Treasury, as tokens or as a claim");
        assertEq(pm.delta(address(hook), id), 0, "the hook leaves no outstanding delta");
    }
}

